script:
// Main script: score and greeting.
// Your paddle is the Me handle; it runs along the rail at the bottom.
// The opponent at the top follows the ball – the It handle is attached to it, so you feel where it is.

state.me = 0;
state.opponent = 0;
speak("Pong! Your paddle is at the bottom. The higher the tone, the further right the ball is. A clear tone means the ball is above your paddle.");

onKey("Space", () => speak(`${state.me} to ${state.opponent}`, { interrupt: true }));

levels.script:
// Field coordinates are relative to the center; world() converts them to Studio coordinates.
const CENTER = 180;
const world = (x, y) => ({ x: x + CENTER, y });
const field = (p) => ({ x: p.x - CENTER, y: p.y });
const OPPONENT_Y = 78;
const PLAYER_Y = 132;
const OPPONENT_SPEED = 20;

const ball = level.ball("Ball");
const opponent = level.entity("Opponent");
const opponentGoal = level.zone("Opponent Goal");
const playerGoal = level.zone("Player Goal");

opponent.follow({ get position() { return world(field(ball).x, OPPONENT_Y); } }, { speed: OPPONENT_SPEED });
// Let the It handle follow the live Ball position.
it.switchTo(ball);

let serveTimer = 0;
let nextServeAngle = 0;
function serve(direction) {
  ball.stopBall();
  ball.position = world(0, (OPPONENT_Y + PLAYER_Y) / 2);
  nextServeAngle = (direction < 0 ? Math.PI : 0) + (Math.random() - 0.5) * 2 * (ball.serveAngle ?? 0.6);
  serveTimer = 1.5;
}

function point(forMe) {
  if (forMe) state.me++; else state.opponent++;
  sound.beep(forMe ? 880 : 220, 300);
  speak(`${forMe ? "Your point" : "Point for the opponent"}. ${state.me} to ${state.opponent}.`, { interrupt: true });
  serve(forMe ? -1 : 1);
}

serve(1);
let lastBeep = 0;
panto.onFrame((dt, time) => {
  if (serveTimer > 0) {
    serveTimer -= dt;
    if (serveTimer <= 0) ball.launch({ angle: nextServeAngle });
    return;
  }

  const position = field(ball);
  const mine = field(me);
  if (playerGoal.contains(ball)) return point(false);
  if (opponentGoal.contains(ball)) return point(true);

  const progress = (position.y - OPPONENT_Y) / (PLAYER_Y - OPPONENT_Y);
  const velocity = ball.velocity;
  const interval = velocity.y > 0 ? 0.35 - progress * 0.25 : 0.4;
  if (time - lastBeep < interval) return;
  lastBeep = time;
  const aboveMe = Math.abs(position.x - mine.x) <= 16;
  sound.beep(600 + position.x * 6, 40, { volume: 0.15, type: aboveMe ? "sine" : "triangle" });
});
